import UIKit
import WebKit
import AVFoundation

final class ViewController: UIViewController, WKNavigationDelegate, WKUIDelegate, WKScriptMessageHandler {

    // Preserved @IBOutlet name & type so Main.storyboard generated by safari-web-extension-converter
    // unarchives cleanly without NSUnknownKeyException before viewDidLoad() upgrades the WKWebView.
    @IBOutlet var webView: WKWebView!

    private let appHomeURL = URL(string: "https://www.heybroc.com/?platform=ios")!
    private let appToolsURL = URL(string: "https://www.heybroc.com/tools?platform=ios")!

    private var loadingOverlay: UIView?
    private var loadingSpinner: UIActivityIndicatorView?
    private var safetyHideWorkItem: DispatchWorkItem?
    private var isShowingOfflineFallback = false

    override var preferredStatusBarStyle: UIStatusBarStyle {
        return .darkContent
    }

    override func viewDidLoad() {
        super.viewDidLoad()

        let bg = UIColor(red: 0.973, green: 0.980, blue: 0.988, alpha: 1.0) // #F8FAFC
        view.backgroundColor = bg

        if let storyboardWebView = self.webView {
            storyboardWebView.navigationDelegate = nil
            storyboardWebView.uiDelegate = nil
            storyboardWebView.removeFromSuperview()
        }

        let config = WKWebViewConfiguration()
        config.allowsInlineMediaPlayback = true
        config.mediaTypesRequiringUserActionForPlayback = []
        config.websiteDataStore = .default()
        config.applicationNameForUserAgent = "HeyBrocIOS/2.1.0"
        config.userContentController.add(self, name: "controller")

        let freshWebView = WKWebView(frame: .zero, configuration: config)
        freshWebView.translatesAutoresizingMaskIntoConstraints = false
        freshWebView.navigationDelegate = self
        freshWebView.uiDelegate = self
        freshWebView.allowsBackForwardNavigationGestures = true
        freshWebView.isOpaque = false
        freshWebView.backgroundColor = bg
        freshWebView.scrollView.backgroundColor = bg
        freshWebView.scrollView.isScrollEnabled = true
        freshWebView.scrollView.bounces = true
        freshWebView.scrollView.contentInsetAdjustmentBehavior = .automatic

        let refreshControl = UIRefreshControl()
        refreshControl.tintColor = UIColor(red: 0.059, green: 0.478, blue: 0.290, alpha: 1.0)
        refreshControl.addTarget(self, action: #selector(handlePullToRefresh(_:)), for: .valueChanged)
        freshWebView.scrollView.refreshControl = refreshControl

        self.webView = freshWebView
        view.addSubview(freshWebView)

        let bottomBar = buildBottomBar()
        view.addSubview(bottomBar)

        NSLayoutConstraint.activate([
            freshWebView.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor),
            freshWebView.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            freshWebView.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            freshWebView.bottomAnchor.constraint(equalTo: bottomBar.topAnchor),

            bottomBar.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            bottomBar.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            bottomBar.bottomAnchor.constraint(equalTo: view.bottomAnchor)
        ])

        setupLoadingOverlay(above: freshWebView, below: bottomBar)
        loadAppURL(appHomeURL)

        NotificationCenter.default.addObserver(
            forName: Notification.Name("HeyBrocOpenLiveShopNotification"),
            object: nil,
            queue: .main
        ) { [weak self] _ in
            guard let self = self, self.presentedViewController == nil else { return }
            self.presentLiveStoreBrowser()
        }
    }

    private func buildBottomBar() -> UIView {
        let container = UIView()
        container.translatesAutoresizingMaskIntoConstraints = false
        container.backgroundColor = UIColor.white

        let topBorder = UIView()
        topBorder.translatesAutoresizingMaskIntoConstraints = false
        topBorder.backgroundColor = UIColor(red: 0.886, green: 0.910, blue: 0.941, alpha: 1.0)
        container.addSubview(topBorder)

        let stack = UIStackView()
        stack.translatesAutoresizingMaskIntoConstraints = false
        stack.axis = .horizontal
        stack.distribution = .fillEqually
        stack.alignment = .fill
        stack.spacing = 6
        container.addSubview(stack)

        let scannerBtn = makeBarButton(title: "🥦 Scanner", primary: false, action: #selector(tapScannerHome))
        let liveShopBtn = makeBarButton(title: "🛒 Live Shop", primary: true, action: #selector(tapLiveShop))
        let barcodeBtn = makeBarButton(title: "📷 Barcode", primary: false, action: #selector(tapBarcodeScanner))
        let safariBtn = makeBarButton(title: "⚡ iPhone Pill", primary: false, action: #selector(tapSafariSetup))

        stack.addArrangedSubview(scannerBtn)
        stack.addArrangedSubview(liveShopBtn)
        stack.addArrangedSubview(barcodeBtn)
        stack.addArrangedSubview(safariBtn)

        NSLayoutConstraint.activate([
            topBorder.topAnchor.constraint(equalTo: container.topAnchor),
            topBorder.leadingAnchor.constraint(equalTo: container.leadingAnchor),
            topBorder.trailingAnchor.constraint(equalTo: container.trailingAnchor),
            topBorder.heightAnchor.constraint(equalToConstant: 1.0 / UIScreen.main.scale),

            stack.topAnchor.constraint(equalTo: container.topAnchor, constant: 8),
            stack.leadingAnchor.constraint(equalTo: container.leadingAnchor, constant: 10),
            stack.trailingAnchor.constraint(equalTo: container.trailingAnchor, constant: -10),
            stack.bottomAnchor.constraint(equalTo: container.safeAreaLayoutGuide.bottomAnchor, constant: -6),
            stack.heightAnchor.constraint(equalToConstant: 40)
        ])

        return container
    }

    private func makeBarButton(title: String, primary: Bool, action: Selector) -> UIButton {
        let btn = UIButton(type: .system)
        btn.setTitle(title, for: .normal)
        btn.titleLabel?.font = UIFont.systemFont(ofSize: 12, weight: .bold)
        btn.titleLabel?.adjustsFontSizeToFitWidth = true
        btn.titleLabel?.minimumScaleFactor = 0.78
        btn.layer.cornerRadius = 12
        if primary {
            btn.backgroundColor = UIColor(red: 0.925, green: 0.992, blue: 0.961, alpha: 1.0)
            btn.setTitleColor(UIColor(red: 0.047, green: 0.396, blue: 0.251, alpha: 1.0), for: .normal)
            btn.layer.borderWidth = 1
            btn.layer.borderColor = UIColor(red: 0.525, green: 0.937, blue: 0.675, alpha: 1.0).cgColor
        } else {
            btn.backgroundColor = UIColor(red: 0.945, green: 0.961, blue: 0.976, alpha: 1.0)
            btn.setTitleColor(UIColor(red: 0.059, green: 0.090, blue: 0.165, alpha: 1.0), for: .normal)
        }
        btn.addTarget(self, action: action, for: .touchUpInside)
        return btn
    }

    private func setupLoadingOverlay(above targetView: UIView, below bottomBar: UIView) {
        let overlay = UIView()
        overlay.translatesAutoresizingMaskIntoConstraints = false
        overlay.backgroundColor = UIColor(red: 0.973, green: 0.980, blue: 0.988, alpha: 1.0)

        let stack = UIStackView()
        stack.translatesAutoresizingMaskIntoConstraints = false
        stack.axis = .vertical
        stack.alignment = .center
        stack.spacing = 12

        let spinner = UIActivityIndicatorView(style: .large)
        spinner.color = UIColor(red: 0.086, green: 0.639, blue: 0.290, alpha: 1.0)
        spinner.startAnimating()

        let titleLabel = UILabel()
        titleLabel.text = "HeyBroc Clean Food Scanner"
        titleLabel.font = UIFont.systemFont(ofSize: 18, weight: .heavy)
        titleLabel.textColor = UIColor(red: 0.059, green: 0.090, blue: 0.165, alpha: 1.0)

        let subLabel = UILabel()
        subLabel.text = "Loading 0–100 grocery scores & Clean Swaps…"
        subLabel.font = UIFont.systemFont(ofSize: 13.5, weight: .medium)
        subLabel.textColor = UIColor(red: 0.278, green: 0.333, blue: 0.412, alpha: 1.0)
        subLabel.textAlignment = .center
        subLabel.numberOfLines = 2

        stack.addArrangedSubview(spinner)
        stack.addArrangedSubview(titleLabel)
        stack.addArrangedSubview(subLabel)
        overlay.addSubview(stack)
        view.insertSubview(overlay, belowSubview: bottomBar)

        NSLayoutConstraint.activate([
            overlay.topAnchor.constraint(equalTo: targetView.topAnchor),
            overlay.leadingAnchor.constraint(equalTo: targetView.leadingAnchor),
            overlay.trailingAnchor.constraint(equalTo: targetView.trailingAnchor),
            overlay.bottomAnchor.constraint(equalTo: targetView.bottomAnchor),

            stack.centerXAnchor.constraint(equalTo: overlay.centerXAnchor),
            stack.centerYAnchor.constraint(equalTo: overlay.centerYAnchor),
            stack.leadingAnchor.constraint(greaterThanOrEqualTo: overlay.leadingAnchor, constant: 24),
            stack.trailingAnchor.constraint(lessThanOrEqualTo: overlay.trailingAnchor, constant: -24)
        ])

        self.loadingOverlay = overlay
        self.loadingSpinner = spinner
    }

    private func showLoadingOverlay() {
        safetyHideWorkItem?.cancel()
        loadingOverlay?.alpha = 1.0
        loadingOverlay?.isHidden = false
        loadingSpinner?.startAnimating()

        let item = DispatchWorkItem { [weak self] in
            self?.hideLoadingOverlay()
        }
        safetyHideWorkItem = item
        DispatchQueue.main.asyncAfter(deadline: .now() + 6.0, execute: item)
    }

    private func hideLoadingOverlay() {
        safetyHideWorkItem?.cancel()
        webView.scrollView.refreshControl?.endRefreshing()
        guard let overlay = loadingOverlay, !overlay.isHidden else { return }
        UIView.animate(withDuration: 0.22, animations: {
            overlay.alpha = 0.0
        }, completion: { [weak self] _ in
            overlay.isHidden = true
            self?.loadingSpinner?.stopAnimating()
        })
    }

    private func loadAppURL(_ url: URL) {
        isShowingOfflineFallback = false
        showLoadingOverlay()
        var request = URLRequest(url: url, cachePolicy: .useProtocolCachePolicy, timeoutInterval: 18)
        request.setValue("ios", forHTTPHeaderField: "X-HeyBroc-Platform")
        webView.load(request)
    }

    private func loadOfflineFallback() {
        guard !isShowingOfflineFallback else {
            hideLoadingOverlay()
            return
        }
        isShowingOfflineFallback = true
        if let localURL = Bundle.main.url(forResource: "Main", withExtension: "html"),
           let resRoot = Bundle.main.resourceURL {
            webView.loadFileURL(localURL, allowingReadAccessTo: resRoot)
        } else {
            hideLoadingOverlay()
        }
    }

    // MARK: - Native Bar Actions

    @objc private func handlePullToRefresh(_ sender: UIRefreshControl) {
        if isShowingOfflineFallback || webView.url == nil || webView.url?.isFileURL == true {
            loadAppURL(appHomeURL)
        } else {
            webView.reload()
        }
    }

    @objc private func tapScannerHome() {
        if isShowingOfflineFallback || webView.url?.host?.contains("heybroc.com") != true || webView.url?.path.hasPrefix("/tools") == true {
            loadAppURL(appHomeURL)
        } else {
            webView.evaluateJavaScript("window.scrollTo({ top: 0, behavior: 'smooth' });", completionHandler: nil)
        }
    }

    @objc private func tapLiveShop() {
        presentLiveStoreBrowser()
    }

    @objc private func tapBarcodeScanner() {
        presentBarcodeScanner()
    }

    @objc private func tapSafariSetup() {
        presentSafariSetupSheet()
    }

    @objc private func tapTools() {
        loadAppURL(appToolsURL)
    }

    private func openSystemSettings() {
        if let url = URL(string: UIApplication.openSettingsURLString) {
            UIApplication.shared.open(url, options: [:], completionHandler: nil)
        }
    }

    private func syncNativePrefsToWebView() {
        guard let data = try? JSONSerialization.data(withJSONObject: HeyBrocSharedPrefs.dietaryWatchlist, options: []),
              let jsonStr = String(data: data, encoding: .utf8) else { return }
        let escaped = jsonStr.replacingOccurrences(of: "\\", with: "\\\\").replacingOccurrences(of: "'", with: "\\'")
        let js = """
        try {
          localStorage.setItem('heybroc_dietary_watchlist', '\(escaped)');
          window.dispatchEvent(new Event('storage'));
        } catch (_) {}
        """
        webView.evaluateJavaScript(js, completionHandler: nil)
    }

    private func presentLiveStoreBrowser(initialStoreKey: String? = nil) {
        let browser = LiveStoreBrowserViewController(
            initialStoreKey: initialStoreKey,
            onPreferencesUpdated: { [weak self] in
                self?.syncNativePrefsToWebView()
            }
        )
        browser.modalPresentationStyle = .fullScreen
        present(browser, animated: true)
    }

    private func presentSafariSetupSheet() {
        let sheet = SafariSetupSheetViewController(
            onOpenLiveStore: { [weak self] storeKey in
                self?.presentLiveStoreBrowser(initialStoreKey: storeKey)
            },
            onOpenSettings: { [weak self] in
                self?.openSystemSettings()
            },
            onOpenExternalURL: { url in
                UIApplication.shared.open(url, options: [:], completionHandler: nil)
            },
            onOpenToolsShortcut: { [weak self] in
                guard let self = self else { return }
                self.loadAppURL(self.appToolsURL)
            }
        )
        if #available(iOS 15.0, *), let pres = sheet.sheetPresentationController {
            pres.detents = [.large()]
            pres.prefersGrabberVisible = true
            pres.preferredCornerRadius = 24
        }
        present(sheet, animated: true)
    }

    private func presentBarcodeScanner() {
        let scanner = NativeBarcodeScannerViewController { [weak self] rawCode in
            self?.handleScannedBarcode(rawCode)
        }
        scanner.modalPresentationStyle = .fullScreen
        present(scanner, animated: true)
    }

    private func handleScannedBarcode(_ code: String) {
        let digits = code.filter { $0.isNumber }
        guard !digits.isEmpty else { return }
        let normalized = (digits.count == 13 && digits.hasPrefix("0")) ? String(digits.dropFirst()) : digits

        if isShowingOfflineFallback || webView.url?.host?.contains("heybroc.com") != true {
            var comps = URLComponents(url: appHomeURL, resolvingAgainstBaseURL: false)
            comps?.queryItems = [
                URLQueryItem(name: "platform", value: "ios"),
                URLQueryItem(name: "q", value: normalized)
            ]
            if let target = comps?.url {
                loadAppURL(target)
            }
            return
        }

        let js = "(typeof window.__heybrocNativeBarcode === 'function') ? (window.__heybrocNativeBarcode('\(normalized)'), true) : false;"
        webView.evaluateJavaScript(js) { [weak self] result, _ in
            guard let self = self else { return }
            let handled = (result as? Bool) == true
            if !handled {
                var comps = URLComponents(url: self.appHomeURL, resolvingAgainstBaseURL: false)
                comps?.queryItems = [
                    URLQueryItem(name: "platform", value: "ios"),
                    URLQueryItem(name: "q", value: normalized)
                ]
                if let target = comps?.url {
                    self.loadAppURL(target)
                }
            }
        }
    }

    // MARK: - WKScriptMessageHandler

    func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
        guard message.name == "controller" else { return }
        var payloadDict: [String: Any]?
        let action: String
        if let str = message.body as? String {
            action = str
        } else if let dict = message.body as? [String: Any], let cmd = dict["action"] as? String {
            action = cmd
            payloadDict = dict
        } else {
            return
        }

        switch action {
        case "open-settings", "open-preferences":
            openSystemSettings()
        case "open-safari-setup":
            presentSafariSetupSheet()
        case "open-live-shop":
            let storeKey = payloadDict?["store"] as? String
            presentLiveStoreBrowser(initialStoreKey: storeKey)
        case "sync-preferences":
            if let dietary = payloadDict?["dietaryWatchlist"] as? [String] {
                HeyBrocSharedPrefs.dietaryWatchlist = dietary
            }
            if let family = payloadDict?["familyWatchlist"] as? [String] {
                HeyBrocSharedPrefs.familyWatchlist = family
            }
            if let preferSB = payloadDict?["preferStoreBrand"] as? Bool {
                HeyBrocSharedPrefs.preferStoreBrand = preferSB
            }
            if let activeStore = payloadDict?["store"] as? String, !activeStore.isEmpty {
                HeyBrocSharedPrefs.activeStore = activeStore
            }
        case "open-barcode-scanner":
            presentBarcodeScanner()
        case "reload-app", "open-scanner":
            loadAppURL(appHomeURL)
        default:
            break
        }
    }

    // MARK: - WKNavigationDelegate

    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        hideLoadingOverlay()
    }

    func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: Error) {
        hideLoadingOverlay()
    }

    func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: Error) {
        let nsErr = error as NSError
        if nsErr.domain == NSURLErrorDomain && nsErr.code == NSURLErrorCancelled {
            return
        }
        loadOfflineFallback()
    }

    func webView(_ webView: WKWebView, decidePolicyFor navigationAction: WKNavigationAction, decisionHandler: @escaping (WKNavigationActionPolicy) -> Void) {
        guard let url = navigationAction.request.url else {
            decisionHandler(.allow)
            return
        }

        if url.isFileURL {
            decisionHandler(.allow)
            return
        }

        let scheme = (url.scheme ?? "").lowercased()
        if scheme == "heybroc" {
            let host = (url.host ?? "").lowercased()
            if host == "settings" {
                openSystemSettings()
            } else if host == "safari" {
                presentSafariSetupSheet()
            } else if host == "liveshop" {
                presentLiveStoreBrowser()
            } else if host == "barcode" {
                presentBarcodeScanner()
            }
            decisionHandler(.cancel)
            return
        }

        if ["mailto", "tel", "sms", "shortcuts"].contains(scheme) {
            UIApplication.shared.open(url, options: [:], completionHandler: nil)
            decisionHandler(.cancel)
            return
        }

        let host = (url.host ?? "").lowercased()
        if host == "stripe.com" || host.hasSuffix(".stripe.com") {
            let alert = UIAlertController(
                title: "HeyBroc Pro on iOS",
                message: "Pro membership is managed natively in the HeyBroc iOS app — sign in to sync an existing account.",
                preferredStyle: .alert
            )
            alert.addAction(UIAlertAction(title: "OK", style: .default))
            present(alert, animated: true)
            decisionHandler(.cancel)
            return
        }

        let isAllowedInAppHost =
            host == "heybroc.com" ||
            host.hasSuffix(".heybroc.com") ||
            host == "cleancart-teal.vercel.app"

        if !isAllowedInAppHost && navigationAction.navigationType == .linkActivated {
            UIApplication.shared.open(url, options: [:], completionHandler: nil)
            decisionHandler(.cancel)
            return
        }

        decisionHandler(.allow)
    }

    // MARK: - WKUIDelegate

    func webView(_ webView: WKWebView, createWebViewWith configuration: WKWebViewConfiguration, for navigationAction: WKNavigationAction, windowFeatures: WKWindowFeatures) -> WKWebView? {
        guard navigationAction.targetFrame == nil, let url = navigationAction.request.url else {
            return nil
        }
        let host = (url.host ?? "").lowercased()
        if host == "stripe.com" || host.hasSuffix(".stripe.com") {
            return nil
        }
        let isInApp =
            host == "heybroc.com" ||
            host.hasSuffix(".heybroc.com") ||
            host == "cleancart-teal.vercel.app"

        if isInApp {
            webView.load(navigationAction.request)
        } else {
            UIApplication.shared.open(url, options: [:], completionHandler: nil)
        }
        return nil
    }

    func webView(_ webView: WKWebView, runJavaScriptAlertPanelWithMessage message: String, initiatedByFrame frame: WKFrameInfo, completionHandler: @escaping () -> Void) {
        let alert = UIAlertController(title: "HeyBroc", message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "OK", style: .default) { _ in completionHandler() })
        present(alert, animated: true)
    }

    func webView(_ webView: WKWebView, runJavaScriptConfirmPanelWithMessage message: String, initiatedByFrame frame: WKFrameInfo, completionHandler: @escaping (Bool) -> Void) {
        let alert = UIAlertController(title: "HeyBroc", message: message, preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "Cancel", style: .cancel) { _ in completionHandler(false) })
        alert.addAction(UIAlertAction(title: "OK", style: .default) { _ in completionHandler(true) })
        present(alert, animated: true)
    }

    @available(iOS 15.0, *)
    func webView(_ webView: WKWebView, requestMediaCapturePermissionFor origin: WKSecurityOrigin, initiatedByFrame frame: WKFrameInfo, type: WKMediaCaptureType, decisionHandler: @escaping (WKPermissionDecision) -> Void) {
        let host = origin.host.lowercased()
        if host == "heybroc.com" || host.hasSuffix(".heybroc.com") || host == "cleancart-teal.vercel.app" {
            decisionHandler(.grant)
        } else {
            decisionHandler(.prompt)
        }
    }
}

// MARK: - Complete iPhone Grocery Bubble, Share Sheet & Back-Tap Setup Sheet

private final class SafariSetupSheetViewController: UIViewController {
    private let onOpenLiveStore: (String?) -> Void
    private let onOpenSettings: () -> Void
    private let onOpenExternalURL: (URL) -> Void
    private let onOpenToolsShortcut: () -> Void

    init(
        onOpenLiveStore: @escaping (String?) -> Void,
        onOpenSettings: @escaping () -> Void,
        onOpenExternalURL: @escaping (URL) -> Void,
        onOpenToolsShortcut: @escaping () -> Void
    ) {
        self.onOpenLiveStore = onOpenLiveStore
        self.onOpenSettings = onOpenSettings
        self.onOpenExternalURL = onOpenExternalURL
        self.onOpenToolsShortcut = onOpenToolsShortcut
        super.init(nibName: nil, bundle: nil)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        view.backgroundColor = UIColor(red: 0.973, green: 0.980, blue: 0.988, alpha: 1.0)

        let scroll = UIScrollView()
        scroll.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(scroll)

        let content = UIStackView()
        content.translatesAutoresizingMaskIntoConstraints = false
        content.axis = .vertical
        content.spacing = 14
        scroll.addSubview(content)

        let headerRow = UIStackView()
        headerRow.axis = .horizontal
        headerRow.alignment = .center
        headerRow.distribution = .equalSpacing

        let titleLabel = UILabel()
        titleLabel.text = "🥦 4 Ways to Shop on iPhone"
        titleLabel.font = UIFont.systemFont(ofSize: 20, weight: .heavy)
        titleLabel.textColor = UIColor(red: 0.059, green: 0.090, blue: 0.165, alpha: 1.0)
        titleLabel.numberOfLines = 2

        let closeBtn = UIButton(type: .system)
        closeBtn.setTitle("Done", for: .normal)
        closeBtn.titleLabel?.font = UIFont.systemFont(ofSize: 15, weight: .bold)
        closeBtn.setTitleColor(UIColor(red: 0.059, green: 0.478, blue: 0.290, alpha: 1.0), for: .normal)
        closeBtn.addTarget(self, action: #selector(tapClose), for: .touchUpInside)

        headerRow.addArrangedSubview(titleLabel)
        headerRow.addArrangedSubview(closeBtn)
        content.addArrangedSubview(headerRow)

        // 1. In-App Live Store Browser (Permanent Floating Bubble — Zero Tapping!)
        let liveCard = makeCard(borderColor: UIColor(red: 0.525, green: 0.937, blue: 0.675, alpha: 1.0), bgColor: UIColor(red: 0.925, green: 0.992, blue: 0.961, alpha: 1.0))
        liveCard.addArrangedSubview(makeBadge("⭐ ZERO SETUP • AUTOMATIC PERMANENT BUBBLE"))
        liveCard.addArrangedSubview(makeHeading("1. 🛒 Live Store Browser Inside HeyBroc"))
        liveCard.addArrangedSubview(makeBody("Sign into Walmart, Instacart, Target, Amazon Fresh, Costco, Sam's Club, Kroger or ALDI once. HeyBroc's floating broccoli pill stays on screen automatically across every food item—just like Android!"))

        let storesRow = UIStackView()
        storesRow.axis = .horizontal
        storesRow.distribution = .fillEqually
        storesRow.spacing = 6
        storesRow.addArrangedSubview(makeStoreBtn(title: "Walmart", storeKey: "walmart"))
        storesRow.addArrangedSubview(makeStoreBtn(title: "Instacart", storeKey: "instacart"))
        storesRow.addArrangedSubview(makeStoreBtn(title: "Target", storeKey: "target"))
        storesRow.addArrangedSubview(makeStoreBtn(title: "Amazon", storeKey: "amazon"))
        liveCard.addArrangedSubview(storesRow)
        content.addArrangedSubview(liveCard)

        // 2. Native Grocery Apps Share Sheet (`↑ Share -> 🥦 HeyBroc`)
        let shareCard = makeCard()
        shareCard.addArrangedSubview(makeBadge("INSIDE WALMART / INSTACART / TARGET APPS"))
        shareCard.addArrangedSubview(makeHeading("2. 📤 Tap ↑ Share → 🥦 HeyBroc"))
        shareCard.addArrangedSubview(makeBody("Shopping inside the native Walmart, Instacart, Target, Costco or Amazon app? Tap the ↑ Share icon on any food item and tap 🥦 HeyBroc for an instant slide-up 0–100 score card, 🌱 Pesticide toggle & 1-tap Clean Swap without leaving your cart."))
        content.addArrangedSubview(shareCard)

        // 3. Back Tap / Action Button Screen Scanner (Set Up Once)
        let backTapCard = makeCard()
        backTapCard.addArrangedSubview(makeBadge("SET UP ONCE • DOUBLE-TAP ON ANY SCREEN"))
        backTapCard.addArrangedSubview(makeHeading("3. ⚡ Back-Tap / Action Button Scanner"))
        backTapCard.addArrangedSubview(makeBody("1. Open Shortcuts → tap + → Add Action → search \"HeyBroc\" → pick \"Scan Grocery Screenshot with HeyBroc\" (add \"Take Screenshot\" right above it and pass Screenshot into it).\n2. Open Settings → Accessibility → Touch → Back Tap → Double Tap → choose your HeyBroc shortcut.\nAfter this 1-time setup, double-tap the back of your iPhone on any food item to see a live score banner!"))

        let shortcutRow = UIStackView()
        shortcutRow.axis = .horizontal
        shortcutRow.distribution = .fillEqually
        shortcutRow.spacing = 8

        let openShortcutsBtn = makeActionBtn(title: "⚡ Open Shortcuts", filled: true, action: #selector(tapOpenShortcutsApp))
        let openSettingsBtn = makeActionBtn(title: "⚙️ iPhone Settings", filled: false, action: #selector(tapOpenSettings))
        shortcutRow.addArrangedSubview(openShortcutsBtn)
        shortcutRow.addArrangedSubview(openSettingsBtn)
        backTapCard.addArrangedSubview(shortcutRow)
        content.addArrangedSubview(backTapCard)

        // 4. Safari Browser Floating Extension
        let safariCard = makeCard()
        safariCard.addArrangedSubview(makeBadge("SAFARI BROWSER EXTENSION"))
        safariCard.addArrangedSubview(makeHeading("4. 🧭 Safari Automatic Floating Pill"))
        safariCard.addArrangedSubview(makeBody("Shopping grocery websites in Safari? Enable Settings → Apps → Safari → Extensions → HeyBroc → Allow for an automatic floating score pill."))
        let safariSettingsBtn = makeActionBtn(title: "⚙️ Enable Safari Extension in Settings", filled: false, action: #selector(tapOpenSettings))
        safariCard.addArrangedSubview(safariSettingsBtn)
        content.addArrangedSubview(safariCard)

        NSLayoutConstraint.activate([
            scroll.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor),
            scroll.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            scroll.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            scroll.bottomAnchor.constraint(equalTo: view.bottomAnchor),

            content.topAnchor.constraint(equalTo: scroll.contentLayoutGuide.topAnchor, constant: 20),
            content.leadingAnchor.constraint(equalTo: scroll.frameLayoutGuide.leadingAnchor, constant: 20),
            content.trailingAnchor.constraint(equalTo: scroll.frameLayoutGuide.trailingAnchor, constant: -20),
            content.bottomAnchor.constraint(equalTo: scroll.contentLayoutGuide.bottomAnchor, constant: -24)
        ])
    }

    private func makeCard(
        borderColor: UIColor = UIColor(red: 0.886, green: 0.910, blue: 0.941, alpha: 1.0),
        bgColor: UIColor = .white
    ) -> UIStackView {
        let card = UIStackView()
        card.axis = .vertical
        card.spacing = 8
        card.isLayoutMarginsRelativeArrangement = true
        card.layoutMargins = UIEdgeInsets(top: 14, left: 14, bottom: 14, right: 14)
        card.backgroundColor = bgColor
        card.layer.cornerRadius = 16
        card.layer.borderWidth = 1
        card.layer.borderColor = borderColor.cgColor
        return card
    }

    private func makeBadge(_ text: String) -> UILabel {
        let lbl = UILabel()
        lbl.text = text
        lbl.font = UIFont.systemFont(ofSize: 10.5, weight: .heavy)
        lbl.textColor = UIColor(red: 0.047, green: 0.396, blue: 0.251, alpha: 1.0)
        return lbl
    }

    private func makeHeading(_ text: String) -> UILabel {
        let lbl = UILabel()
        lbl.text = text
        lbl.font = UIFont.systemFont(ofSize: 15.5, weight: .heavy)
        lbl.textColor = UIColor(red: 0.059, green: 0.090, blue: 0.165, alpha: 1.0)
        lbl.numberOfLines = 0
        return lbl
    }

    private func makeBody(_ text: String) -> UILabel {
        let lbl = UILabel()
        lbl.text = text
        lbl.font = UIFont.systemFont(ofSize: 13, weight: .regular)
        lbl.textColor = UIColor(red: 0.278, green: 0.333, blue: 0.412, alpha: 1.0)
        lbl.numberOfLines = 0
        return lbl
    }

    private func makeStoreBtn(title: String, storeKey: String) -> UIButton {
        let btn = UIButton(type: .system)
        btn.setTitle(title, for: .normal)
        btn.accessibilityIdentifier = storeKey
        btn.titleLabel?.font = UIFont.systemFont(ofSize: 12.5, weight: .heavy)
        btn.backgroundColor = UIColor(red: 0.059, green: 0.478, blue: 0.290, alpha: 1.0)
        btn.setTitleColor(.white, for: .normal)
        btn.layer.cornerRadius = 10
        btn.heightAnchor.constraint(equalToConstant: 38).isActive = true
        btn.addTarget(self, action: #selector(tapLaunchLiveStore(_:)), for: .touchUpInside)
        return btn
    }

    private func makeActionBtn(title: String, filled: Bool, action: Selector) -> UIButton {
        let btn = UIButton(type: .system)
        btn.setTitle(title, for: .normal)
        btn.titleLabel?.font = UIFont.systemFont(ofSize: 13, weight: .heavy)
        btn.layer.cornerRadius = 12
        btn.heightAnchor.constraint(equalToConstant: 42).isActive = true
        if filled {
            btn.backgroundColor = UIColor(red: 0.059, green: 0.478, blue: 0.290, alpha: 1.0)
            btn.setTitleColor(.white, for: .normal)
        } else {
            btn.backgroundColor = .white
            btn.setTitleColor(UIColor(red: 0.059, green: 0.090, blue: 0.165, alpha: 1.0), for: .normal)
            btn.layer.borderWidth = 1
            btn.layer.borderColor = UIColor(red: 0.796, green: 0.835, blue: 0.882, alpha: 1.0).cgColor
        }
        btn.addTarget(self, action: action, for: .touchUpInside)
        return btn
    }

    @objc private func tapClose() {
        dismiss(animated: true)
    }

    @objc private func tapLaunchLiveStore(_ sender: UIButton) {
        let storeKey = sender.accessibilityIdentifier
        dismiss(animated: true) { [onOpenLiveStore] in
            onOpenLiveStore(storeKey)
        }
    }

    @objc private func tapOpenShortcutsApp() {
        if let url = URL(string: "shortcuts://") {
            onOpenExternalURL(url)
        }
    }

    @objc private func tapOpenSettings() {
        onOpenSettings()
    }
}

// MARK: - Native Hardware Barcode Scanner (AVCaptureSession)

private final class NativeBarcodeScannerViewController: UIViewController, AVCaptureMetadataOutputObjectsDelegate {
    private let onCodeDetected: (String) -> Void
    private let session = AVCaptureSession()
    private let sessionQueue = DispatchQueue(label: "com.heybroc.app.barcode-session")
    private var previewLayer: AVCaptureVideoPreviewLayer?
    private var didDetect = false
    private var statusLabel: UILabel?
    private var settingsButton: UIButton?

    init(onCodeDetected: @escaping (String) -> Void) {
        self.onCodeDetected = onCodeDetected
        super.init(nibName: nil, bundle: nil)
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) has not been implemented")
    }

    override var preferredStatusBarStyle: UIStatusBarStyle {
        return .lightContent
    }

    override func viewDidLoad() {
        super.viewDidLoad()
        view.backgroundColor = .black

        let preview = AVCaptureVideoPreviewLayer(session: session)
        preview.videoGravity = .resizeAspectFill
        view.layer.addSublayer(preview)
        self.previewLayer = preview

        setupChromeUI()
        checkCameraPermissionAndStart()
    }

    override func viewDidLayoutSubviews() {
        super.viewDidLayoutSubviews()
        previewLayer?.frame = view.bounds
    }

    override func viewWillDisappear(_ animated: Bool) {
        super.viewWillDisappear(animated)
        stopSession()
    }

    private func setupChromeUI() {
        let reticle = UIView()
        reticle.translatesAutoresizingMaskIntoConstraints = false
        reticle.backgroundColor = UIColor.clear
        reticle.layer.cornerRadius = 18
        reticle.layer.borderWidth = 3
        reticle.layer.borderColor = UIColor(red: 0.133, green: 0.773, blue: 0.369, alpha: 1.0).cgColor
        view.addSubview(reticle)

        let closeBtn = UIButton(type: .system)
        closeBtn.translatesAutoresizingMaskIntoConstraints = false
        closeBtn.setTitle("✕ Close", for: .normal)
        closeBtn.titleLabel?.font = UIFont.systemFont(ofSize: 15, weight: .bold)
        closeBtn.backgroundColor = UIColor(white: 0.12, alpha: 0.82)
        closeBtn.setTitleColor(.white, for: .normal)
        closeBtn.layer.cornerRadius = 20
        closeBtn.contentEdgeInsets = UIEdgeInsets(top: 10, left: 16, bottom: 10, right: 16)
        closeBtn.addTarget(self, action: #selector(tapCancel), for: .touchUpInside)
        view.addSubview(closeBtn)

        let torchBtn = UIButton(type: .system)
        torchBtn.translatesAutoresizingMaskIntoConstraints = false
        torchBtn.setTitle("🔦 Light", for: .normal)
        torchBtn.titleLabel?.font = UIFont.systemFont(ofSize: 15, weight: .bold)
        torchBtn.backgroundColor = UIColor(white: 0.12, alpha: 0.82)
        torchBtn.setTitleColor(.white, for: .normal)
        torchBtn.layer.cornerRadius = 20
        torchBtn.contentEdgeInsets = UIEdgeInsets(top: 10, left: 16, bottom: 10, right: 16)
        torchBtn.addTarget(self, action: #selector(tapToggleTorch), for: .touchUpInside)
        view.addSubview(torchBtn)

        let hint = UILabel()
        hint.translatesAutoresizingMaskIntoConstraints = false
        hint.text = "Center food or cosmetic UPC barcode inside frame"
        hint.font = UIFont.systemFont(ofSize: 15, weight: .bold)
        hint.textColor = .white
        hint.textAlignment = .center
        hint.numberOfLines = 0
        view.addSubview(hint)
        self.statusLabel = hint

        let settingsBtn = UIButton(type: .system)
        settingsBtn.translatesAutoresizingMaskIntoConstraints = false
        settingsBtn.setTitle("Allow Camera in Settings", for: .normal)
        settingsBtn.titleLabel?.font = UIFont.systemFont(ofSize: 15, weight: .bold)
        settingsBtn.backgroundColor = UIColor(red: 0.086, green: 0.639, blue: 0.290, alpha: 1.0)
        settingsBtn.setTitleColor(.white, for: .normal)
        settingsBtn.layer.cornerRadius = 14
        settingsBtn.contentEdgeInsets = UIEdgeInsets(top: 12, left: 20, bottom: 12, right: 20)
        settingsBtn.isHidden = true
        settingsBtn.addTarget(self, action: #selector(tapOpenSettings), for: .touchUpInside)
        view.addSubview(settingsBtn)
        self.settingsButton = settingsBtn

        NSLayoutConstraint.activate([
            closeBtn.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor, constant: 14),
            closeBtn.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 16),

            torchBtn.topAnchor.constraint(equalTo: view.safeAreaLayoutGuide.topAnchor, constant: 14),
            torchBtn.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -16),

            reticle.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            reticle.centerYAnchor.constraint(equalTo: view.centerYAnchor, constant: -20),
            reticle.widthAnchor.constraint(equalToConstant: 270),
            reticle.heightAnchor.constraint(equalToConstant: 165),

            hint.topAnchor.constraint(equalTo: reticle.bottomAnchor, constant: 22),
            hint.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 28),
            hint.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -28),

            settingsBtn.topAnchor.constraint(equalTo: hint.bottomAnchor, constant: 16),
            settingsBtn.centerXAnchor.constraint(equalTo: view.centerXAnchor)
        ])
    }

    private func checkCameraPermissionAndStart() {
        switch AVCaptureDevice.authorizationStatus(for: .video) {
        case .authorized:
            configureAndStartSession()
        case .notDetermined:
            AVCaptureDevice.requestAccess(for: .video) { [weak self] granted in
                DispatchQueue.main.async {
                    if granted {
                        self?.configureAndStartSession()
                    } else {
                        self?.showPermissionDenied()
                    }
                }
            }
        default:
            showPermissionDenied()
        }
    }

    private func showPermissionDenied() {
        statusLabel?.text = "Camera permission is needed to scan product barcodes."
        settingsButton?.isHidden = false
    }

    private func configureAndStartSession() {
        sessionQueue.async { [weak self] in
            guard let self = self else { return }
            self.session.beginConfiguration()
            if self.session.canSetSessionPreset(.high) {
                self.session.sessionPreset = .high
            }

            guard let device = AVCaptureDevice.default(for: .video),
                  let input = try? AVCaptureDeviceInput(device: device),
                  self.session.canAddInput(input) else {
                self.session.commitConfiguration()
                DispatchQueue.main.async {
                    self.statusLabel?.text = "Camera unavailable on this device — search by product name or UPC."
                }
                return
            }
            self.session.addInput(input)

            let output = AVCaptureMetadataOutput()
            if self.session.canAddOutput(output) {
                self.session.addOutput(output)
                output.setMetadataObjectsDelegate(self, queue: DispatchQueue.main)
                let desired: [AVMetadataObject.ObjectType] = [.ean13, .ean8, .upce, .code128, .code39, .itf14]
                let supported = desired.filter { output.availableMetadataObjectTypes.contains($0) }
                if !supported.isEmpty {
                    output.metadataObjectTypes = supported
                }
            }

            self.session.commitConfiguration()
            self.session.startRunning()
        }
    }

    private func stopSession() {
        let captureSession = self.session
        sessionQueue.async {
            if captureSession.isRunning {
                captureSession.stopRunning()
            }
        }
    }

    func metadataOutput(_ output: AVCaptureMetadataOutput, didOutput metadataObjects: [AVMetadataObject], from connection: AVCaptureConnection) {
        guard !didDetect else { return }
        for item in metadataObjects {
            if let readable = item as? AVMetadataMachineReadableCodeObject,
               let raw = readable.stringValue?.trimmingCharacters(in: .whitespacesAndNewlines),
               !raw.isEmpty {
                didDetect = true
                let generator = UIImpactFeedbackGenerator(style: .medium)
                generator.impactOccurred()
                stopSession()
                dismiss(animated: true) { [onCodeDetected] in
                    onCodeDetected(raw)
                }
                return
            }
        }
    }

    @objc private func tapCancel() {
        stopSession()
        dismiss(animated: true)
    }

    @objc private func tapToggleTorch() {
        guard let device = AVCaptureDevice.default(for: .video), device.hasTorch else { return }
        try? device.lockForConfiguration()
        device.torchMode = (device.torchMode == .on) ? .off : .on
        device.unlockForConfiguration()
    }

    @objc private func tapOpenSettings() {
        if let url = URL(string: UIApplication.openSettingsURLString) {
            UIApplication.shared.open(url, options: [:], completionHandler: nil)
        }
    }
}
